import{_ as o,o as r,c as n,j as a,a as s,G as p,aa as d,B as i}from"./chunks/framework.VLjJFeoF.js";const k=JSON.parse('{"title":"介绍","description":"","frontmatter":{"author":"Choi Yang","contributors":["HearLing"]},"headers":[],"relativePath":"docs/patterns/guide/index.md","filePath":"docs/patterns/guide/index.md","lastUpdated":1769531044000}'),c={name:"docs/patterns/guide/index.md"};function l(_,e,f,m,u,b){const t=i("ArticleMetadata");return r(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1769531044000"},[e[0]||(e[0]=a("h1",{id:"介绍",tabindex:"-1"},[s("介绍 "),a("a",{class:"header-anchor",href:"#介绍","aria-label":'Permalink to "介绍"'},"​")],-1)),p(t,{article:{}}),e[1]||(e[1]=d('<p>在这个专栏，我们会一起学习前端设计模式，设计模式是软件开发的一个基本部分，因为它们为软件设计中经常出现的问题提供了典型的解决方案。</p><p>大学阶段，有一位 java 老师，写了一本设计模式的书籍，当时就和我们说设计模式很重要，尤其是在工作之后。</p><p>现如今，当我逐步学习知识的时候，会发现设计模式无处不在，可以把它理解为某个特定的解决方案，而现在许多前端框架，从古老的架构到一步一步迭代到现如今，期间也总结了很多设计模式，不断的优化与修改，形成了新的设计模式，React Hooks 当中也出现了很多设计模式，这些都值得我们去探索。</p><p>然而，设计模式可以说是一种思想，它并没有提供特定的软件片段，可以说是一些概念，但就是这些思想，能够帮助我们解决很多问题并且优化改善我们的 web app。</p><p>专栏内容主要学习自 <a href="https://www.patterns.dev/" target="_blank" rel="noreferrer">Patterns.dev</a>。</p><blockquote><p>a free book on design patterns and component patterns for building powerful web apps with vanilla JavaScript and React.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>内容并非完全翻译，会穿插一些内容，如若内容存在错误与不足点，可提 PR 共建内容，在文档主页会显示参与者头像。当然，更推荐阅读英文原文，感谢各位参与，我们马上进入设计模式的世界。</p></div>',7))])}const v=o(c,[["render",l]]);export{k as __pageData,v as default};
